<script setup lang="ts">import { onMounted, ref } from 'vue'; import { ElMessage } from 'element-plus'; import http from '../../api/http'; const apps=ref<any[]>([]); onMounted(async()=>{apps.value=(await http.get('/apps/store')).data}); async function install(app:any){await http.post(`/apps/${app.id}/install`); ElMessage.success('安装成功，请刷新菜单');}</script>
<template><el-card><template #header>应用商店</template><el-empty v-if="!apps.length" description="暂无可安装应用" /><el-row :gutter="16"><el-col v-for="app in apps" :key="app.id" :span="8"><el-card shadow="hover"><h3>{{ app.name }}</h3><p>{{ app.description }}</p><el-tag>{{ app.version }}</el-tag><el-button type="primary" link @click="install(app)">安装</el-button></el-card></el-col></el-row></el-card></template>
